## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/peClassification.ts`

```typescript
// PE Risk Classification Algorithm
// Strictly based on: 2026 AHA/ACC/ACCP/ACEP/CHEST/SCAI/SHM/SIR/SVM/SVN
// Guideline for the Evaluation and Management of Acute Pulmonary Embolism in Adults
// Circulation. 2026;153:e977-e1051. DOI: 10.1161/CIR.0000000000001415
// + RCT data: HI-PEITHO, PEERLESS, STORM PE, PEITHO

export interface PatientData {
  // Demographics
  name: string;
  age: number;
  weight: number; // kg

  // Vitals
  heartRate: number;
  systolicBP: number;
  diastolicBP: number;
  respiratoryRate: number;
  spO2: number;
  temperature: number; // °C

  // Clinical presentation
  symptomatic: boolean; // false = incidental/subclinical (Category A)
  subsegmental: boolean; // true = subsegmental PE (B1 vs B2)

  // Imaging — RV assessment (echo preferred over CT per guideline)
  rvDilation: boolean; // RV/LV ratio > 0.9 on CT or echo
  rvDysfunction: boolean; // Echo: TAPSE reduced, McConnell's sign, RV free wall hypokinesis, etc.
  tapse: number | null; // cm — TAPSE <1.6 cm indicates RV dysfunction (bedside or formal echo)
  clotBurden: "low" | "moderate" | "high"; // based on CT

  // Biomarkers (Class 1 recommendation to measure for Categories C-E)
  troponin: number; // ng/mL (high-sensitivity)
  troponinElevated: boolean;
  bnp: number; // pg/mL (or NT-proBNP)
  bnpElevated: boolean;
  lactate: number; // mmol/L — Class 1 recommendation for Categories C-E

  // Clinical
  alteredMentalStatus: boolean;
  needsVasopressors: boolean;
  cardiacArrest: boolean;
  syncope: boolean;
  cancer: boolean;
  heartFailure: boolean;
  chronicLungDisease: boolean;

  // Hemodynamic details (for D/E subcategorization per guideline)
  // D1: Transient hypotension — SBP <90 that resolved
  transientHypotension: boolean;
  // D2: Normotensive shock — signs of organ hypoperfusion (rising lactate, creatinine,
  //     altered mental status) despite normal blood pressure
  normotensiveShock: boolean;
  // E1: Recurrent or persistent hypotension with cardiogenic shock
  persistentHypotension: boolean;
  // E2: Refractory cardiogenic shock or cardiac arrest
  refractoryShock: boolean;

  // Respiratory support — determines R modifier
  supplementalO2: boolean;
  // >6L nasal cannula or non-rebreather mask (D-level R modifier)
  highFlowO2: boolean;
  // Hypoxemic respiratory failure or ventilatory failure (E-level R modifier)
  mechanicalVentilation: boolean;

  // Contraindications to thrombolysis / CDT
  recentSurgery: boolean; // within 3 weeks
  recentStroke: boolean; // hemorrhagic or ischemic within 3 months
  activeBleeding: boolean;
  bleedingDiathesis: boolean; // known coagulopathy
  intracranialNeoplasm: boolean;
  recentHeadTrauma: boolean; // within 3 weeks
  aorticDissection: boolean;
  thrombocytopenia: boolean; // platelets < 100k
  anticoagulantUse: boolean; // on therapeutic anticoagulation (INR >1.7 etc.)
  pregnancyOrPostpartum: boolean;
  recentGIBleed: boolean; // within 3 months
  uncontrolledHTN: boolean; // SBP > 180 despite treatment

  // DVT Assessment
  proximalDVT: boolean; // popliteal, femoral, or iliac vein thrombus
  dvtLocation: "none" | "popliteal" | "femoral" | "iliac" | "iliofemoral";
  dvtBilateral: boolean;
  phlegmasia: boolean; // limb-threatening compromise

  // IVC Filter
  ivcFilterIndicated: boolean; // absolute contraindication to anticoagulation
  ivcFilterPlaced: boolean;
  ivcFilterType: "none" | "retrievable" | "permanent";
  anticoagContraindication: boolean; // absolute contraindication to anticoagulation
  recurrentPEOnAnticoag: boolean; // recurrent PE despite therapeutic anticoagulation
}

export interface ContraindicationResult {
  systemicThrombolysis: {
    eligible: boolean;
    absolute: string[];
    relative: string[];
  };
  cdt: {
    eligible: boolean;
    absolute: string[];
    relative: string[];
  };
  anticoagulation: {
    eligible: boolean;
    cautions: string[];
  };
}

export interface ScoreBreakdown {
  sPESI: { score: number; details: string[] };
  BOVA: { score: number; stage: string; details: string[] };
  NEWS: { score: number; risk: string; details: string[] };
}

export type PECategory =
  | "A"
  | "B1" | "B2"
  | "C1" | "C2" | "C3"
  | "D1" | "D2"
  | "E1" | "E2";

export type RiskLevel = "critical" | "high" | "moderate" | "low" | "minimal";

export interface ESC2019Equivalent {
  category: string; // e.g. "High", "Intermediate-High", "Intermediate-Low", "Low"
  description: string;
}

export interface ClassificationResult {
  category: PECategory;
  label: string;
  riskLevel: RiskLevel;
  respiratoryModifier: boolean;
  respiratoryModifierDetail: string;
  treatment: string;
  rationale: string[];
  scores: ScoreBreakdown;
  evidence: EvidenceCitation[];
  hemodynamicStatus: "unstable" | "stable";
  contraindications: ContraindicationResult;
  esc2019Equivalent: ESC2019Equivalent;
}

export interface EvidenceCitation {
  source: string;
  finding: string;
  year: number;
}

// sPESI Calculator
// Per guideline: sPESI 0 = low clinical severity (Category B)
// sPESI ≥1 = elevated clinical severity (Category C)
export function calculateSPESI(data: PatientData): { score: number; details: string[] } {
  let score = 0;
  const details: string[] = [];
  if (data.age > 80) { score++; details.push("Age > 80"); }
  if (data.cancer) { score++; details.push("Active cancer"); }
  if (data.heartFailure || data.chronicLungDisease) { score++; details.push("Cardiopulmonary disease"); }
  if (data.heartRate >= 110) { score++; details.push("HR ≥ 110"); }
  if (data.systolicBP < 100) { score++; details.push("SBP < 100 mmHg"); }
  if (data.spO2 < 90) { score++; details.push("SpO2 < 90%"); }
  return { score, details };
}

// BOVA Score Calculator
export function calculateBOVA(data: PatientData): { score: number; stage: string; details: string[] } {
  let score = 0;
  const details: string[] = [];
  if (data.heartRate >= 110) { score += 1; details.push("HR ≥ 110 (+1)"); }
  if (data.systolicBP < 90) { score += 2; details.push("SBP < 90 mmHg (+2)"); }
  else if (data.systolicBP < 100) { score += 2; details.push("SBP 90-100 mmHg (+2)"); }
  const tapseAbnormal = data.tapse !== null && data.tapse < 1.6;
  if (data.rvDysfunction || data.rvDilation || tapseAbnormal) {
    const tapseNote = tapseAbnormal ? ` [TAPSE ${data.tapse} cm]` : "";
    score += 2; details.push(`RV dysfunction (+2)${tapseNote}`);
  }
  if (data.troponinElevated) { score += 2; details.push("Elevated troponin (+2)"); }
  let stage: string;
  if (score <= 2) stage = "Stage I (low risk)";
  else if (score <= 4) stage = "Stage II (intermediate)";
  else stage = "Stage III (high risk)";
  return { score, stage, details };
}

// NEWS Score Calculator
export function calculateNEWS(data: PatientData): { score: number; risk: string; details: string[] } {
  let score = 0;
  const details: string[] = [];

  if (data.respiratoryRate <= 8) { score += 3; details.push("RR ≤8 (+3)"); }
  else if (data.respiratoryRate <= 11) { score += 1; details.push("RR 9-11 (+1)"); }
  else if (data.respiratoryRate <= 20) { /* 0 */ }
  else if (data.respiratoryRate <= 24) { score += 2; details.push("RR 21-24 (+2)"); }
  else { score += 3; details.push("RR ≥25 (+3)"); }

  if (data.spO2 <= 91) { score += 3; details.push("SpO2 ≤91% (+3)"); }
  else if (data.spO2 <= 93) { score += 2; details.push("SpO2 92-93% (+2)"); }
  else if (data.spO2 <= 95) { score += 1; details.push("SpO2 94-95% (+1)"); }

  if (data.supplementalO2) { score += 2; details.push("On supplemental O2 (+2)"); }

  if (data.temperature <= 35.0) { score += 3; details.push("Temp ≤35.0°C (+3)"); }
  else if (data.temperature <= 36.0) { score += 1; details.push("Temp 35.1-36.0°C (+1)"); }
  else if (data.temperature <= 38.0) { /* 0 */ }
  else if (data.temperature <= 39.0) { score += 1; details.push("Temp 38.1-39.0°C (+1)"); }
  else { score += 2; details.push("Temp ≥39.1°C (+2)"); }

  if (data.systolicBP <= 90) { score += 3; details.push("SBP ≤90 (+3)"); }
  else if (data.systolicBP <= 100) { score += 2; details.push("SBP 91-100 (+2)"); }
  else if (data.systolicBP <= 110) { score += 1; details.push("SBP 101-110 (+1)"); }
  else if (data.systolicBP <= 219) { /* 0 */ }
  else { score += 3; details.push("SBP ≥220 (+3)"); }

  if (data.heartRate <= 40) { score += 3; details.push("HR ≤40 (+3)"); }
  else if (data.heartRate <= 50) { score += 1; details.push("HR 41-50 (+1)"); }
  else if (data.heartRate <= 90) { /* 0 */ }
  else if (data.heartRate <= 110) { score += 1; details.push("HR 91-110 (+1)"); }
  else if (data.heartRate <= 130) { score += 2; details.push("HR 111-130 (+2)"); }
  else { score += 3; details.push("HR ≥131 (+3)"); }

  if (data.alteredMentalStatus) { score += 3; details.push("Altered mental status (+3)"); }

  let risk: string;
  if (score <= 4) risk = "Low";
  else if (score <= 6) risk = "Medium";
  else risk = "High";

  return { score, risk, details };
}

// Contraindication Assessment
export function assessContraindications(data: PatientData): ContraindicationResult {
  const systolicAbsolute: string[] = [];
  const systolicRelative: string[] = [];
  const cdtAbsolute: string[] = [];
  const cdtRelative: string[] = [];
  const acCautions: string[] = [];

  if (data.activeBleeding) {
    systolicAbsolute.push("Active bleeding");
    cdtRelative.push("Active bleeding (relative for CDT)");
    acCautions.push("Active bleeding — consider IVC filter");
  }
  if (data.recentStroke) {
    systolicAbsolute.push("Recent stroke (within 3 months)");
    cdtRelative.push("Recent stroke (use caution)");
  }
  if (data.intracranialNeoplasm) {
    systolicAbsolute.push("Intracranial neoplasm");
    cdtAbsolute.push("Intracranial neoplasm");
  }
  if (data.recentHeadTrauma) {
    systolicAbsolute.push("Recent head trauma (within 3 weeks)");
    cdtRelative.push("Recent head trauma");
  }
  if (data.aorticDissection) {
    systolicAbsolute.push("Known/suspected aortic dissection");
    cdtAbsolute.push("Aortic dissection");
  }
  if (data.recentSurgery) {
    systolicAbsolute.push("Recent major surgery (within 3 weeks)");
    cdtRelative.push("Recent surgery (proceed with caution, lower dose)");
  }
  if (data.bleedingDiathesis) {
    systolicRelative.push("Known bleeding diathesis/coagulopathy");
    cdtRelative.push("Bleeding diathesis");
    acCautions.push("Bleeding diathesis — careful dosing, monitor closely");
  }
  if (data.thrombocytopenia) {
    systolicRelative.push("Thrombocytopenia (platelets < 100k)");
    cdtRelative.push("Thrombocytopenia");
    acCautions.push("Thrombocytopenia — consider platelet transfusion threshold");
  }
  if (data.anticoagulantUse) {
    systolicRelative.push("Already on therapeutic anticoagulation (INR > 1.7)");
    cdtRelative.push("Supratherapeutic anticoagulation");
  }
  if (data.pregnancyOrPostpartum) {
    systolicRelative.push("Pregnancy or postpartum (within 1 week)");
    cdtRelative.push("Pregnancy/postpartum (multidisciplinary decision)");
    acCautions.push("Pregnancy — DOACs contraindicated (Class 3: Harm), use LMWH or UFH only");
  }
  if (data.recentGIBleed) {
    systolicRelative.push("Recent GI bleeding (within 3 months)");
    cdtRelative.push("Recent GI bleeding");
    acCautions.push("Recent GI bleed — GI consultation recommended");
  }
  if (data.uncontrolledHTN) {
    systolicRelative.push("Uncontrolled hypertension (SBP > 180)");
    cdtRelative.push("Uncontrolled hypertension");
  }

  return {
    systemicThrombolysis: {
      eligible: systolicAbsolute.length === 0,
      absolute: systolicAbsolute,
      relative: systolicRelative,
    },
    cdt: {
      eligible: cdtAbsolute.length === 0,
      absolute: cdtAbsolute,
      relative: cdtRelative,
    },
    anticoagulation: {
      eligible: !data.activeBleeding,
      cautions: acCautions,
    },
  };
}

// Respiratory Modifier (R) — per guideline, can be appended to any subcategory
// when hypoxia, tachypnea, or escalating oxygen requirements are present
function assessRespiratoryModifier(data: PatientData, majorCategory: "C" | "D" | "E"): { active: boolean; detail: string } {
  if (majorCategory === "C") {
    // R for C: O₂ <90%, RR ≥30, need supplemental O₂
    const triggers: string[] = [];
    if (data.spO2 < 90) triggers.push("SpO₂ <90%");
    if (data.respiratoryRate >= 30) triggers.push("RR ≥30");
    if (data.supplementalO2) triggers.push("Needs supplemental O₂");
    return { active: triggers.length > 0, detail: triggers.join(", ") };
  }
  if (majorCategory === "D") {
    // R for D: >6L nasal cannula or NRB mask
    const triggers: string[] = [];
    if (data.highFlowO2) triggers.push(">6L nasal cannula or NRB mask");
    if (data.supplementalO2 && !data.highFlowO2) triggers.push("On supplemental O₂");
    return { active: triggers.length > 0, detail: triggers.join(", ") };
  }
  // E: Hypoxemic respiratory failure or ventilatory failure
  const triggers: string[] = [];
  if (data.mechanicalVentilation) triggers.push("Hypoxemic respiratory failure or ventilatory failure");
  if (data.highFlowO2 && !data.mechanicalVentilation) triggers.push(">6L nasal cannula or NRB mask");
  return { active: triggers.length > 0, detail: triggers.join(", ") };
}

// =============================================================================
// Main Classification Algorithm
// 2026 AHA/ACC Acute PE Clinical Categories (A through E)
// Creager MA et al. Circulation. 2026;153:e977-e1051
//
// Categories are assigned by the MOST SEVERE clinical, laboratory, and imaging
// indicator. Patients may transition between categories over time.
// =============================================================================
export function classifyPE(data: PatientData): ClassificationResult {
  const sPESI = calculateSPESI(data);
  const bova = calculateBOVA(data);
  const news = calculateNEWS(data);
  const scores: ScoreBreakdown = { sPESI: { ...sPESI }, BOVA: { ...bova }, NEWS: { ...news } };
  const contraindications = assessContraindications(data);
  const lyticsSafe = contraindications.systemicThrombolysis.eligible;
  const cdtSafe = contraindications.cdt.eligible;

  // TAPSE <1.6 cm is an echocardiographic marker of RV dysfunction
  // Per 2026 AHA/ACC Guidelines: Echo preferred over CT for RV assessment in unstable patients
  const tapseAbnormal = data.tapse !== null && data.tapse < 1.6;
  const hasAbnormalRV = data.rvDilation || data.rvDysfunction || tapseAbnormal;
  const hasAbnormalBiomarker = data.troponinElevated || data.bnpElevated;
  // Per guideline: sPESI ≥1, PESI III-V, or Hestia ≥1 = elevated clinical severity
  const elevatedSeverityScore = sPESI.score >= 1;

  // ==================== Category A: Subclinical ====================
  // Incidental PE found on imaging done for another reason, no symptoms
  // Per guideline: Can be safely discharged from the ED (Class 2a)
  if (!data.symptomatic) {
    return {
      category: "A",
      label: "Subclinical — Incidental and Asymptomatic",
      riskLevel: "minimal",
      respiratoryModifier: false,
      respiratoryModifierDetail: "",
      treatment: "Risk category consistent with populations in which anticoagulation has been studied. Consideration may be given to ED discharge without hospitalization in appropriate clinical context (Class 2a). Observation may be reasonable if isolated subsegmental with low clot burden.",
      rationale: [
        "Incidental PE finding — patient is asymptomatic",
        "Risk-benefit of anticoagulation should be individualized",
        `sPESI: ${sPESI.score}`,
      ],
      scores,
      evidence: [
        { source: "2026 AHA/ACC PE Guidelines §3.2", finding: "Category A: Subclinical PE — patients can be safely discharged from the ED (Class 2a)", year: 2026 },
      ],
      hemodynamicStatus: "stable",
      contraindications,
      esc2019Equivalent: { category: "Not classified", description: "Incidental/subclinical PE was not a distinct category in ESC 2019. Would generally be managed as low risk." },
    };
  }

  // ==================== Category E: Cardiopulmonary Failure ====================
  // E2: Refractory cardiogenic shock or cardiac arrest
  // Per guideline: Systemic thrombolysis is reasonable (Class 2a).
  // Surgical embolectomy NOT recommended over other options like VA-ECMO.
  if (data.refractoryShock || data.cardiacArrest) {
    const resp = assessRespiratoryModifier(data, "E");
    let treatment = "Risk category consistent with populations in which systemic thrombolysis has been studied (Class 2a). Consideration may be given to CDT/MT or VA-ECMO for circulatory support in appropriate clinical context. Surgical embolectomy not favored over other advanced options.";
    if (!lyticsSafe && cdtSafe) {
      treatment = "⚠️ Systemic lysis contraindicated — Consideration may be given to CDT/MT or VA-ECMO in appropriate clinical context. Urgent multidisciplinary PERT consultation recommended.";
    } else if (!lyticsSafe && !cdtSafe) {
      treatment = "⚠️ Systemic lysis AND CDT contraindicated — Consideration may be given to VA-ECMO or surgical embolectomy in appropriate clinical context. Urgent multidisciplinary PERT consultation recommended.";
    }
    // Sedation warning per guideline
    treatment += " ⚠️ AVOID deep sedation/intubation unless clinically necessary — cardiac arrest rates 19-28% after anesthesia induction in PE with RV dysfunction (Class 3: Harm).";
    return {
      category: "E2",
      label: "Cardiopulmonary Failure — Refractory Shock / Cardiac Arrest",
      riskLevel: "critical",
      respiratoryModifier: resp.active,
      respiratoryModifierDetail: resp.detail,
      treatment,
      rationale: [
        data.cardiacArrest ? "Cardiac arrest" : "Refractory cardiogenic shock",
        "Immediate intervention required — activate PERT (Class 1, Level B-NR)",
        `NEWS score: ${news.score} (${news.risk})`,
        `Lactate: ${data.lactate} mmol/L (Class 1 recommendation to measure)`,
      ],
      scores,
      evidence: [
        { source: "2026 AHA/ACC PE Guidelines §4.4", finding: "Category E2: Systemic thrombolysis is reasonable. Surgical embolectomy not recommended over VA-ECMO.", year: 2026 },
        { source: "2026 AHA/ACC PE Guidelines §4.2.3", finding: "Deep sedation and mechanical ventilation — Class 3: Harm unless clinically necessary in Categories C-E", year: 2026 },
        { source: "STORM PE Trial", finding: "Demonstrated feasibility of CDT in massive PE when systemic therapy contraindicated", year: 2023 },
      ],
      hemodynamicStatus: "unstable",
      contraindications,
      esc2019Equivalent: { category: "High Risk", description: "ESC 2019 High Risk (Massive PE): Hemodynamic instability with cardiac arrest or sustained hypotension requiring vasopressors." },
    };
  }

  // E1: Recurrent or persistent hypotension with cardiogenic shock
  // Per guideline: Advanced therapies are "reasonable" — systemic thrombolysis,
  // CDL, MT, or surgical embolectomy (Class 2a)
  if (data.persistentHypotension || (data.needsVasopressors && data.systolicBP < 90)) {
    const resp = assessRespiratoryModifier(data, "E");
    let treatment = "Risk category consistent with populations in which advanced therapies have been studied (Class 2a). Consideration may be given to systemic thrombolysis, CDT, MT, or surgical embolectomy in appropriate clinical context. Anticoagulation with LMWH preferred over UFH (Class 1). PERT activation recommended.";
    if (!lyticsSafe && cdtSafe) {
      treatment = "⚠️ Systemic lysis contraindicated — Consideration may be given to CDT/MT or surgical embolectomy in appropriate clinical context (Class 2a). Anticoagulation + vasopressor support.";
    } else if (!lyticsSafe && !cdtSafe) {
      treatment = "⚠️ Lysis & CDT contraindicated — Consideration may be given to surgical embolectomy or VA-ECMO in appropriate clinical context. Urgent multidisciplinary PERT consultation recommended.";
    }
    treatment += " ⚠️ AVOID deep sedation unless clinically necessary (Class 3: Harm).";
    return {
      category: "E1",
      label: "Cardiopulmonary Failure — Persistent Hypotension with Cardiogenic Shock",
      riskLevel: "critical",
      respiratoryModifier: resp.active,
      respiratoryModifierDetail: resp.detail,
      treatment,
      rationale: [
        "Recurrent or persistent hypotension with cardiogenic shock",
        `SBP ${data.systolicBP} mmHg`,
        data.needsVasopressors ? "Requiring vasopressor support" : "",
        "Activate PERT (Class 1, Level B-NR)",
        `NEWS score: ${news.score} (${news.risk})`,
        `Lactate: ${data.lactate} mmol/L (Class 1 to measure for Cat C-E)`,
      ].filter(Boolean),
      scores,
      evidence: [
        { source: "2026 AHA/ACC PE Guidelines §4.4", finding: "Category E1: Systemic thrombolysis, CDT, MT, or surgical embolectomy are reasonable (Class 2a)", year: 2026 },
        { source: "PEERLESS Trial", finding: "CDT vs MT: no significant difference in 30-day mortality or major bleeding (550 patients)", year: 2024 },
      ],
      hemodynamicStatus: "unstable",
      contraindications,
      esc2019Equivalent: { category: "High Risk", description: "ESC 2019 High Risk (Massive PE): Hemodynamic instability with persistent hypotension or shock." },
    };
  }

  // ==================== Category D: Incipient Cardiopulmonary Failure ====================
  // Per guideline: Advanced therapies "may be considered" (Class 2b) — systemic
  // thrombolysis, CDL, or MT. Hospitalize, ICU-level care.

  // D1: Transient hypotension — SBP <90 that resolved
  if (data.transientHypotension) {
    const resp = assessRespiratoryModifier(data, "D");
    let treatment = "Hospitalization to ICU is generally appropriate. Anticoagulation (LMWH > UFH, Class 1). Risk category consistent with populations in which advanced therapies have been studied (Class 2b). Consideration may be given to systemic thrombolysis, CDT, or MT in appropriate clinical context. PERT activation recommended (Class 1).";
    if (!lyticsSafe && cdtSafe) {
      treatment = "⚠️ Systemic lysis contraindicated — Consideration may be given to CDT/MT in appropriate clinical context (Class 2b). Anticoagulation + ICU monitoring. PERT activation recommended.";
    } else if (!lyticsSafe && !cdtSafe) {
      treatment = "⚠️ Lysis & CDT contraindicated — Anticoagulation + ICU monitoring. Surgical consultation may be appropriate if clinical deterioration occurs. PERT activation recommended.";
    }
    treatment += " ⚠️ AVOID deep sedation unless clinically necessary (Class 3: Harm).";
    return {
      category: "D1",
      label: "Incipient Cardiopulmonary Failure — Transient Hypotension",
      riskLevel: "high",
      respiratoryModifier: resp.active,
      respiratoryModifierDetail: resp.detail,
      treatment,
      rationale: [
        "Transient hypotension (SBP <90 that resolved)",
        `Current SBP: ${data.systolicBP} mmHg`,
        hasAbnormalRV ? "RV dysfunction/dilation present" : "RV assessment recommended (echo preferred, Class 1)",
        "Activate PERT (Class 1, Level B-NR)",
        `NEWS score: ${news.score} (${news.risk})`,
        `Lactate: ${data.lactate} mmol/L`,
      ],
      scores,
      evidence: [
        { source: "2026 AHA/ACC PE Guidelines §4.4", finding: "Categories D1-D2: Advanced therapies may be considered (Class 2b)", year: 2026 },
        { source: "2026 AHA/ACC PE Guidelines §3.2", finding: "Lactate measurement is Class 1 for Categories C-E", year: 2026 },
      ],
      hemodynamicStatus: "unstable",
      contraindications,
      esc2019Equivalent: { category: "Intermediate-High Risk", description: "ESC 2019 Intermediate-High Risk: Transient hypotension that resolved — patient is currently hemodynamically stable. ESC 2019 reserved 'High Risk' for sustained hypotension (>15 min) or cardiac arrest. The 2026 AHA/ACC created Category D to specifically capture these 'incipient failure' patients." },
    };
  }

  // D2: Normotensive shock — signs of organ hypoperfusion despite normal BP
  // "The patient who looks fine on the BP cuff but has rising lactate and creatinine"
  if (data.normotensiveShock) {
    const resp = assessRespiratoryModifier(data, "D");
    let treatment = "Hospitalization to ICU is generally appropriate. Anticoagulation (LMWH > UFH, Class 1). Risk category consistent with populations in which advanced therapies have been studied (Class 2b). Consideration may be given to systemic thrombolysis, CDT, or MT in appropriate clinical context. PERT activation recommended (Class 1).";
    if (!cdtSafe && !lyticsSafe) {
      treatment = "⚠️ Lysis & CDT contraindicated — Anticoagulation + ICU monitoring. Surgical consultation may be appropriate if clinical deterioration occurs. PERT activation recommended.";
    } else if (!lyticsSafe) {
      treatment = "⚠️ Systemic lysis contraindicated — Consideration may be given to CDT/MT in appropriate clinical context (Class 2b). Anticoagulation + ICU. PERT activation recommended.";
    }
    treatment += " ⚠️ AVOID deep sedation unless clinically necessary (Class 3: Harm).";
    return {
      category: "D2",
      label: "Incipient Cardiopulmonary Failure — Normotensive Shock",
      riskLevel: "high",
      respiratoryModifier: resp.active,
      respiratoryModifierDetail: resp.detail,
      treatment,
      rationale: [
        "Normotensive shock — organ hypoperfusion despite normal blood pressure",
        `SBP: ${data.systolicBP} mmHg (normal range but end-organ dysfunction present)`,
        `Lactate: ${data.lactate} mmol/L`,
        hasAbnormalRV ? "RV dysfunction/dilation present" : "",
        data.alteredMentalStatus ? "Altered mental status" : "",
        "Activate PERT (Class 1, Level B-NR)",
      ].filter(Boolean),
      scores,
      evidence: [
        { source: "2026 AHA/ACC PE Guidelines §4.4", finding: "Categories D1-D2: Advanced therapies may be considered (Class 2b)", year: 2026 },
