// ECMO Candidacy Assessment for Massive Pulmonary Embolism
// Based on:
// - Kmiec et al. ASAIO J. 2020;66(2):146-152 (ECMO for massive PE as bridge to therapy)
// - Abdulaziz et al. JAHA. 2024 (MCS for massive PE — review)
// - SAVE Score: Schmidt et al. Eur Heart J. 2015;36:2246-2256
// - ELSO Guidelines for adult cardiac failure
// - ESC 2019 & 2026 AHA/ACC PE Guidelines

import { PatientData, ClassificationResult, PECategory } from "./peClassification";

// ─── ECMO-specific patient data ───────────────────────────────────────────────
export interface ECMOAssessmentInput {
  // From existing PatientData
  patientData: PatientData;
  classificationResult: ClassificationResult;

  // ECMO-specific fields
  preECMOCardiacArrest: boolean;
  diastolicBP6h: number; // Diastolic BP within 6h before potential cannulation
  pulsePressure6h: number; // Pulse pressure within 6h
  peakInspiratoryPressure: number; // cm H₂O
  intubationDurationHours: number; // Hours intubated before ECMO
  hco3: number; // Bicarbonate mmol/L
  acuteRenalFailure: boolean;
  chronicRenalFailure: boolean;
  liverFailure: boolean;
  cnsDysfunction: boolean;

  // Contraindications to ECMO specifically
  unwitnessedArrest: boolean;
  prolongedCPROver60Min: boolean;
  terminalIllness: boolean; // pre-existing terminal condition
  advancedAge: boolean; // generally >75, institution-dependent
  severeBaselineFunctionalImpairment: boolean;
  uncontrolledBleeding: boolean;
  irreversibleNeurologicalInjury: boolean;
  severePVD: boolean; // peripheral vascular disease limiting cannulation
  aorticRegurgitation: boolean; // significant — relative contraindication for VA-ECMO
}

// ─── SAVE Score Calculation ───────────────────────────────────────────────────
// Survival After VA-ECMO (SAVE) Score
// Schmidt et al. Eur Heart J. 2015;36:2246-56
// Range roughly -35 to +17; higher = better prognosis
export interface SAVEScoreResult {
  score: number;
  riskClass: string;
  predictedSurvival: string;
  details: string[];
}

export function calculateSAVEScore(input: ECMOAssessmentInput): SAVEScoreResult {
  let score = 0;
  const details: string[] = [];
  const age = input.patientData.age;
  const weight = input.patientData.weight;

  // Age
  if (age >= 18 && age <= 38) { score += 7; details.push(`Age ${age} (18-38): +7`); }
  else if (age >= 39 && age <= 52) { score += 4; details.push(`Age ${age} (39-52): +4`); }
  else if (age >= 53 && age <= 62) { score += 3; details.push(`Age ${age} (53-62): +3`); }
  else { score += 0; details.push(`Age ${age} (≥63): +0`); }

  // Weight (kg)
  if (weight < 65) { score += 1; details.push(`Weight ${weight}kg (<65): +1`); }
  else if (weight <= 89) { score += 2; details.push(`Weight ${weight}kg (65-89): +2`); }
  else { score += 0; details.push(`Weight ${weight}kg (>89): +0`); }

  // Cause of cardiogenic shock — PE is not myocarditis/VT/VF/transplant
  // PE is not specifically scored positively, but is not a negative modifier
  details.push("Cause: Acute PE (no additional modifier)");

  // Renal
  if (input.chronicRenalFailure) { score -= 6; details.push("Chronic renal failure: -6"); }
  else if (input.acuteRenalFailure) { score -= 3; details.push("Acute renal failure: -3"); }

  // Metabolic acidosis
  if (input.hco3 <= 15) { score -= 3; details.push(`HCO₃ ${input.hco3} (≤15): -3`); }

  // Intubation duration
  if (input.intubationDurationHours >= 30) { score -= 4; details.push(`Intubation ${input.intubationDurationHours}h (≥30): -4`); }
  else if (input.intubationDurationHours >= 11) { score -= 2; details.push(`Intubation ${input.intubationDurationHours}h (11-29): -2`); }
  else { details.push(`Intubation ${input.intubationDurationHours}h (≤10): +0`); }

  // Peak inspiratory pressure
  if (input.peakInspiratoryPressure <= 20) { score += 3; details.push(`PIP ${input.peakInspiratoryPressure} (≤20): +3`); }

  // Pre-ECMO cardiac arrest
  if (input.preECMOCardiacArrest) { score -= 2; details.push("Pre-ECMO cardiac arrest: -2"); }

  // Diastolic BP ≥40 within 6h
  if (input.diastolicBP6h >= 40) { score += 3; details.push(`DBP ${input.diastolicBP6h} (≥40): +3`); }

  // Pulse pressure ≤20
  if (input.pulsePressure6h <= 20) { score -= 2; details.push(`Pulse pressure ${input.pulsePressure6h} (≤20): -2`); }

  // Organ failures
  if (input.liverFailure) { score -= 3; details.push("Liver failure: -3"); }
  if (input.cnsDysfunction) { score -= 3; details.push("CNS dysfunction: -3"); }

  // Lactate <75 mg/dL ≈ <8.3 mmol/L (using mmol/L since that's what we store)
  if (input.patientData.lactate < 8.3) { score += 15; details.push(`Lactate ${input.patientData.lactate} (<8.3 mmol/L): +15`); }

  // Risk class
  let riskClass: string;
  let predictedSurvival: string;
  if (score >= 5) { riskClass = "I (Low Risk)"; predictedSurvival = "~75%"; }
  else if (score >= 1) { riskClass = "II"; predictedSurvival = "~58%"; }
  else if (score >= -4) { riskClass = "III"; predictedSurvival = "~42%"; }
  else if (score >= -9) { riskClass = "IV"; predictedSurvival = "~30%"; }
  else { riskClass = "V (High Risk)"; predictedSurvival = "<20%"; }

  return { score, riskClass, predictedSurvival, details };
}

// ─── Indications Assessment ───────────────────────────────────────────────────
export interface ECMOIndication {
  label: string;
  present: boolean;
  strength: "strong" | "moderate" | "weak";
  source: string;
}

function assessIndications(input: ECMOAssessmentInput): ECMOIndication[] {
  const cat = input.classificationResult.category;
  const d = input.patientData;

  return [
    {
      label: "Cardiac arrest due to PE (ECPR)",
      present: d.cardiacArrest,
      strength: "strong",
      source: "Kmiec et al. 2020; ELSO Guidelines",
    },
    {
      label: "Refractory cardiogenic shock despite vasopressors",
      present: d.refractoryShock || (d.needsVasopressors && d.systolicBP < 90),
      strength: "strong",
      source: "AHA JAHA 2024; Kmiec et al. 2020",
    },
    {
      label: "Persistent hemodynamic instability despite initial therapies",
      present: d.persistentHypotension && d.needsVasopressors,
      strength: "strong",
      source: "ESC 2019; AHA 2026 Cat E1",
    },
    {
      label: "Contraindication to systemic thrombolysis",
      present: !input.classificationResult.contraindications.systemicThrombolysis.eligible,
      strength: "moderate",
      source: "Kmiec et al. 2020; Pavlovic et al. 2014",
    },
    {
      label: "Failed thrombolysis with ongoing hemodynamic compromise",
      present: false, // Would need separate input — kept as potential indication
      strength: "strong",
      source: "ELSO Guidelines; AHA JAHA 2024",
    },
    {
      label: "Severe RV dysfunction with hemodynamic instability",
      present: d.rvDysfunction && (d.systolicBP < 90 || d.needsVasopressors),
      strength: "strong",
      source: "AHA JAHA 2024; 2026 AHA/ACC Guidelines",
    },
    {
      label: "Severe hypoxemic respiratory failure (SpO₂ <85% despite max O₂)",
      present: d.spO2 < 85 && d.mechanicalVentilation,
      strength: "moderate",
      source: "Kmiec et al. 2020 (VV-ECMO consideration)",
    },
    {
      label: "PE category E1 or E2 (AHA/ACC 2026)",
      present: cat === "E1" || cat === "E2",
      strength: "strong",
      source: "2026 AHA/ACC PE Guidelines §4.4",
    },
    {
      label: "Lactate ≥4 mmol/L with hemodynamic compromise",
      present: d.lactate >= 4 && (d.systolicBP < 90 || d.needsVasopressors),
      strength: "moderate",
      source: "George et al. 2017 (lactate ≤6 mmol/L predictive of survival)",
    },
  ];
}

// ─── Contraindications Assessment ─────────────────────────────────────────────
export interface ECMOContraindication {
  label: string;
  present: boolean;
  type: "absolute" | "relative";
  source: string;
}

function assessECMOContraindications(input: ECMOAssessmentInput): ECMOContraindication[] {
