}

// ─── ECMO Configuration Recommendation ───────────────────────────────────────
export type ECMOConfig = "VA-ECMO" | "VV-ECMO" | "VA-ECMO (with VV consideration)" | "Not recommended";

function recommendConfig(input: ECMOAssessmentInput): { config: ECMOConfig; rationale: string } {
  const d = input.patientData;

  // VA-ECMO is preferred for most massive PE (addresses both RV failure + gas exchange)
  if (d.cardiacArrest || d.refractoryShock) {
    return {
      config: "VA-ECMO",
      rationale: "VA-ECMO is the preferred configuration for cardiac arrest or refractory shock due to PE. It unloads the RV and improves oxygenation simultaneously (Kmiec et al. 2020; AHA JAHA 2024).",
    };
  }

  if (d.persistentHypotension || d.needsVasopressors) {
    return {
      config: "VA-ECMO",
      rationale: "VA-ECMO addresses both hemodynamic instability and gas exchange abnormalities in persistent hypotension/cardiogenic shock (AHA JAHA 2024).",
    };
  }

  // VV-ECMO consideration: stable circulation but severe hypoxemia
  if (!d.needsVasopressors && d.systolicBP >= 90 && d.mechanicalVentilation && d.spO2 < 88) {
    return {
      config: "VA-ECMO (with VV consideration)",
      rationale: "Patient has stable circulation but severe respiratory failure. VV-ECMO may be considered if hemodynamics remain stable without high-dose vasopressors. VA-ECMO remains the safer default (Kmiec et al. 2020: VV-ECMO survival 45% vs VA-ECMO 48%, p=0.9).",
    };
  }

  return {
    config: "VA-ECMO",
    rationale: "VA-ECMO is the standard configuration for PE-related MCS, addressing pulmonary circulation and gas exchange abnormalities (AHA JAHA 2024).",
  };
}

// ─── Overall Candidacy Assessment ─────────────────────────────────────────────
export type CandidacyResult = "candidate" | "conditional" | "not_candidate";

export interface ECMOAssessmentResult {
  candidacy: CandidacyResult;
  candidacyLabel: string;
  candidacyRationale: string[];
  indications: ECMOIndication[];
  contraindications: ECMOContraindication[];
  saveScore: SAVEScoreResult;
  recommendedConfig: ECMOConfig;
  configRationale: string;
  keyPrognosticFactors: string[];
  references: { source: string; finding: string; year: number }[];
}

export function assessECMOCandidacy(input: ECMOAssessmentInput): ECMOAssessmentResult {
  const indications = assessIndications(input);
  const contraindications = assessECMOContraindications(input);
  const saveScore = calculateSAVEScore(input);
  const { config, rationale: configRationale } = recommendConfig(input);

  const presentIndications = indications.filter(i => i.present);
  const strongIndications = presentIndications.filter(i => i.strength === "strong");
  const absoluteContra = contraindications.filter(c => c.present && c.type === "absolute");
  const relativeContra = contraindications.filter(c => c.present && c.type === "relative");

  // Determine candidacy
  let candidacy: CandidacyResult;
  let candidacyLabel: string;
  const candidacyRationale: string[] = [];

  if (absoluteContra.length > 0) {
    candidacy = "not_candidate";
    candidacyLabel = "Not a Candidate";
    candidacyRationale.push(`Absolute contraindication(s): ${absoluteContra.map(c => c.label).join("; ")}`);
    if (presentIndications.length > 0) {
      candidacyRationale.push(`Note: ${presentIndications.length} indication(s) present but overridden by absolute contraindication(s)`);
    }
  } else if (strongIndications.length > 0 && relativeContra.length === 0) {
    candidacy = "candidate";
    candidacyLabel = "ECMO Candidate";
    candidacyRationale.push(`${strongIndications.length} strong indication(s) present with no contraindications`);
    candidacyRationale.push(`SAVE score: ${saveScore.score} — Risk Class ${saveScore.riskClass}, predicted survival ${saveScore.predictedSurvival}`);
  } else if (presentIndications.length > 0) {
    candidacy = "conditional";
    candidacyLabel = "Conditional Candidate";
    if (relativeContra.length > 0) {
      candidacyRationale.push(`Relative contraindication(s): ${relativeContra.map(c => c.label).join("; ")}`);
    }
    candidacyRationale.push(`${presentIndications.length} indication(s) present — multidisciplinary evaluation recommended`);
    candidacyRationale.push(`SAVE score: ${saveScore.score} — Risk Class ${saveScore.riskClass}, predicted survival ${saveScore.predictedSurvival}`);
  } else {
    candidacy = "not_candidate";
    candidacyLabel = "Not Indicated";
    candidacyRationale.push("No ECMO indications identified based on current clinical presentation");
    candidacyRationale.push("ECMO is generally reserved for massive PE (AHA/ACC Categories E1/E2) or refractory cases");
  }

  // Prognostic factors
  const keyPrognosticFactors: string[] = [];
  if (input.patientData.lactate <= 6) {
    keyPrognosticFactors.push(`Lactate ${input.patientData.lactate} mmol/L (≤6): favorable prognostic sign (82.4% sensitivity, 84.6% specificity for survival — George et al.)`);
  } else {
    keyPrognosticFactors.push(`Lactate ${input.patientData.lactate} mmol/L (>6): associated with worse outcomes`);
  }
  if (input.preECMOCardiacArrest) {
    keyPrognosticFactors.push("Pre-ECMO cardiac arrest: associated with higher mortality (Yusuff et al. OR 16.71, p=0.0004)");
  }
  if (input.patientData.cancer) {
    keyPrognosticFactors.push("Active malignancy: nonsurvivors tended to have history of malignancy (George et al.)");
  }

  const references = [
    { source: "Kmiec et al. ASAIO J. 2020;66(2):146-152", finding: "ECMO feasible for initial stabilization as bridge to therapy in massive PE. VA-ECMO survival 48%, VV-ECMO 45% (p=0.9). Additional interventions (thrombectomy) vs anticoagulation alone showed similar survival (44% vs 49%, p=0.40).", year: 2020 },
    { source: "AHA JAHA Review: MCS for Massive PE", finding: "VA-ECMO preferred for massive PE — unloads RV, improves oxygenation. Overall systematic review survival >60%. SAVE score and SOFA-RV useful for prognostication.", year: 2024 },
    { source: "Schmidt et al. Eur Heart J. 2015;36:2246-56", finding: "SAVE score predicts survival on VA-ECMO. Score ≥5 associated with ~75% survival; ≤-10 with >80% mortality.", year: 2015 },
    { source: "George et al. J Card Surg. 2018;33:269-74", finding: "Lactate ≤6 mmol/L: 82.4% sensitivity and 84.6% specificity for predicting survival to discharge on VA-ECMO for PE.", year: 2018 },
    { source: "Pasrija et al. Ann Thorac Surg. 2018;105:440-6", finding: "Protocolized VA-ECMO approach for massive PE showed 96% 1-year survival vs 73% with historical surgical approach (p=0.02).", year: 2018 },
    { source: "Scott et al. Resuscitation. 2022;173:1-10", finding: "ECPR for PE-related cardiac arrest: 61% survived to discharge, 88% neurologically intact.", year: 2022 },
  ];

  return {
    candidacy,
    candidacyLabel,
    candidacyRationale,
    indications,
    contraindications,
    saveScore,
    recommendedConfig: candidacy === "not_candidate" ? "Not recommended" : config,
    configRationale: candidacy === "not_candidate" ? "ECMO not recommended based on current assessment" : configRationale,
    keyPrognosticFactors,
    references,
  };
}

// Helper to create default ECMO input from existing patient data
export function createDefaultECMOInput(patientData: PatientData, classificationResult: ClassificationResult): ECMOAssessmentInput {
  return {
    patientData,
    classificationResult,
    preECMOCardiacArrest: patientData.cardiacArrest,
    diastolicBP6h: patientData.diastolicBP,
    pulsePressure6h: patientData.systolicBP - patientData.diastolicBP,
    peakInspiratoryPressure: patientData.mechanicalVentilation ? 25 : 15,
    intubationDurationHours: 0,
    hco3: 22, // default normal
    acuteRenalFailure: false,
    chronicRenalFailure: false,
    liverFailure: false,
    cnsDysfunction: patientData.alteredMentalStatus,
    unwitnessedArrest: false,
    prolongedCPROver60Min: false,
    terminalIllness: false,
    advancedAge: patientData.age > 75,
    severeBaselineFunctionalImpairment: false,
    uncontrolledBleeding: patientData.activeBleeding,
    irreversibleNeurologicalInjury: false,
    severePVD: false,
    aorticRegurgitation: false,
  };
}
